import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int bestNumber = a;
        int bestSteps = 0;
        for(int n = a; n <= b; n++) {
            int steps = 0;
            long value = n;
            while(value != 1) {
                if(value % 2 == 0) {
                    value = value / 2;
                } else {
                    value = 3 * value + 1;
                }
                steps++;
            }
            if(steps > bestSteps) {
                bestSteps = steps;
                bestNumber = n;
            }
        }
        System.out.println(bestNumber);
        System.out.println(bestSteps);
    }
}

