import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] scores = new int[n];
        for(int i = 0; i < n; i++) {
            scores[i] = sc.nextInt();
        }
        int best = scores[0];
        for(int s : scores) {
            if(s > best) {
                best = s;
            }
        }
        int second = 0;
        boolean found = false;
        for(int s : scores) {
            if(s < best) {
                if(!found || s > second) {
                    second = s;
                    found = true;
                }
            }
        }
        if(found) {
            System.out.println(second);
        } else {
            System.out.println("No second place");
        }
    }
}

